using Astrea.BattleActions;
using LittleLeo.Events;
using LittleLeo.Variables;
using UnityEngine;
using UnityEngine.UI;

namespace Astrea;

public class DiceTargetCastSpaceInstance : MonoBehaviour
{
	[Header("Components")]
	[SerializeField]
	private Image dicePlacementImage;

	[Header("Action Instance Reference")]
	[SerializeField]
	private ActionInstanceReference actionInstanceReference;

	[Header("Events")]
	[SerializeField]
	private BoolEvent OnToggleCastButton;

	private Vector3 diceOffset = new Vector3(0.25f, 0.1f, 0f);

	private DiceInstance diceInstance;

	public Vector3 DiceOffset => diceOffset;

	public bool AlreadyHaveADiceInstance => diceInstance != null;

	private void OnEnable()
	{
		dicePlacementImage.raycastTarget = true;
		diceInstance = null;
	}

	public void ActionDrop(DiceInstance diceInstance, bool setDiceInstancePosition = true)
	{
		ChooseDiceAction obj = actionInstanceReference.Value.ActionFace.BattleAction as ChooseDiceAction;
		this.diceInstance = diceInstance;
		if (setDiceInstancePosition)
		{
			diceInstance.transform.position = ReferenceSingleton<InputManager>.Instance.GetDiceOnTargetCastSpacePositionAdjustment(base.transform.position, diceInstance: true);
		}
		diceInstance.DicePlacedOnDiceTargetCastSpace(this);
		obj.DiceSelected(diceInstance);
		dicePlacementImage.raycastTarget = false;
		OnToggleCastButton.Raise(item: true);
	}

	public void ActionRemoved(DiceInstance diceInstance)
	{
		dicePlacementImage.raycastTarget = true;
		ActionInstance value = actionInstanceReference.Value;
		if (value != null)
		{
			ChooseDiceAction chooseDiceAction = value.ActionFace.BattleAction as ChooseDiceAction;
			Debug.Log("ACTION REMOVED: chooseDiceAction" + chooseDiceAction);
			chooseDiceAction.DiceDeselected(diceInstance);
			if (chooseDiceAction.DiceDeselectedTurnOffCastButton())
			{
				OnToggleCastButton.Raise(item: false);
			}
		}
		else
		{
			Debug.Log("----- actionInstance form actionInstanceReference is NULL -----");
		}
		this.diceInstance = null;
	}

	public void OnStoreDiceTargetCastSpaceInstance()
	{
		if (diceInstance != null)
		{
			diceInstance.ResetDiceTargetCastSpaceInstance();
		}
		ReferenceSingleton<PoolHandler>.Instance.StoreObject(base.gameObject);
	}

	public void OnCancelDiceTargetCastSpaceInstance()
	{
		if (diceInstance != null)
		{
			(actionInstanceReference.Value.ActionFace.BattleAction as ChooseDiceAction).DiceDeselected(diceInstance);
			diceInstance.GoBackToOriginalPositionAnimation();
		}
		OnStoreDiceTargetCastSpaceInstance();
	}
}
